import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  const [role, setRole] = useState("");
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();
    if (role === "student") {
      navigate("/dashboard-student");
    } else if (role === "prof") {
      navigate("/dashboard-prof");
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      padding: "20px"
    }}>
      <div style={{
        background: "white",
        borderRadius: "12px",
        boxShadow: "0 10px 30px rgba(0, 0, 0, 0.2)",
        padding: "40px",
        width: "100%",
        maxWidth: "420px",
        textAlign: "center"
      }}>
        <div style={{
          marginBottom: "30px"
        }}>
          <h2 style={{
            color: "#333",
            margin: "0 0 10px 0",
            fontSize: "28px",
            fontWeight: "600"
          }}>Connexion</h2>
          <p style={{
            color: "#666",
            margin: "0",
            fontSize: "16px"
          }}>Accédez à votre espace personnel</p>
        </div>
        
        <form onSubmit={handleLogin}>
          <div style={{
            marginBottom: "20px",
            textAlign: "left"
          }}>
            <label style={{
              display: "block",
              marginBottom: "8px",
              color: "#555",
              fontWeight: "500",
              fontSize: "15px"
            }}>Choisissez votre rôle :</label>
            <select 
              value={role} 
              onChange={(e) => setRole(e.target.value)}
              style={{
                width: "100%",
                padding: "12px 15px",
                border: "1px solid #ddd",
                borderRadius: "8px",
                fontSize: "16px",
                backgroundColor: "#f9f9f9",
                transition: "all 0.3s ease",
                outline: "none",
                boxSizing: "border-box"
              }}
              onFocus={(e) => {
                e.target.style.borderColor = "#667eea";
                e.target.style.backgroundColor = "#fff";
              }}
              onBlur={(e) => {
                e.target.style.borderColor = "#ddd";
                e.target.style.backgroundColor = "#f9f9f9";
              }}
            >
              <option value="">-- Sélectionner --</option>
              <option value="student">Étudiant</option>
              <option value="prof">Professeur</option>
            </select>
          </div>
          
          <button 
            type="submit" 
            style={{
              width: "100%",
              padding: "14px",
              backgroundColor: role ? "#667eea" : "#cccccc",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "16px",
              fontWeight: "600",
              cursor: role ? "pointer" : "not-allowed",
              transition: "all 0.3s ease",
              boxShadow: role ? "0 4px 15px rgba(102, 126, 234, 0.4)" : "none",
              marginTop: "10px"
            }}
            onMouseOver={(e) => {
              if (role) {
                e.target.style.backgroundColor = "#5a6fd8";
                e.target.style.transform = "translateY(-2px)";
              }
            }}
            onMouseOut={(e) => {
              if (role) {
                e.target.style.backgroundColor = "#667eea";
                e.target.style.transform = "translateY(0)";
              }
            }}
          >
            Se connecter
          </button>
        </form>
        
        <p style={{
          marginTop: "25px",
          color: "#666",
          fontSize: "15px"
        }}>
          Pas de compte ? <a href="/register" style={{
            color: "#667eea",
            textDecoration: "none",
            fontWeight: "500",
            transition: "color 0.2s ease"
          }}
          onMouseOver={(e) => e.target.style.color = "#5a6fd8"}
          onMouseOut={(e) => e.target.style.color = "#667eea"}
          >S'inscrire</a>
        </p>
      </div>
    </div>
  );
}

export default Login;
